import{_ as s,o as i,c as a,a0 as t}from"./chunks/framework.l1I-fhud.js";const k=JSON.parse('{"title":"How to deploy a CI gate bundle","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/deploy-a-ci-gate-bundle.md","filePath":"how-to/deploy-a-ci-gate-bundle.md"}'),n={name:"how-to/deploy-a-ci-gate-bundle.md"};function o(d,e,l,h,r,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="how-to-deploy-a-ci-gate-bundle" tabindex="-1">How to deploy a CI gate bundle <a class="header-anchor" href="#how-to-deploy-a-ci-gate-bundle" aria-label="Permalink to &quot;How to deploy a CI gate bundle&quot;">​</a></h1><p>A <code>type: bupha</code> bundle is a CI fleet shipped as tamias content: the payload carries a <code>fleet.toml</code> (the watched repos + runners) and a <code>tamias.yaml</code> manifest whose <code>provider:</code> block declares the systemd units. This guide stands up the org gate bundle — <code>ci-gate</code> from <code>9aia/bupha</code> — end to end. The same steps apply to any <code>type: bupha</code> bundle (e.g. <code>docs-deploy</code>).</p><h2 id="install-the-driver-pack" tabindex="-1">Install the driver pack <a class="header-anchor" href="#install-the-driver-pack" aria-label="Permalink to &quot;Install the driver pack&quot;">​</a></h2><p>The bundle&#39;s driver, <code>tamias-driver-bupha</code>, ships as a payload bin in the bupha product pack (<code>libraries/bupha</code>, <code>type: files</code>). Install it first — the bundle&#39;s <code>deploy</code>/<code>hooks</code>/<code>health</code>/<code>status</code>/<code>logs</code> verbs all dispatch through it.</p><p>The driver binary is a build artifact (<code>drivers/bin/&lt;triple&gt;/</code> is gitignored), so install from a checkout, not a <code>git:</code> ref:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9aia/bupha</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/pack.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # release-builds tamias-driver-bupha</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./libraries/bupha</span></span></code></pre></div><p>(<code>tamias bundle pack libraries/bupha</code> produces a <code>.tgz</code> for hosts that shouldn&#39;t build — install that ref the same way.) <code>--allow-drivers</code> is the consent gate for packages that ship <code>drivers/</code> payloads — see <a href="/tamias/explanation/security.html">Security model</a>. The driver lands in <code>~/.local/share/tamias/drivers/</code>; the provider units exec it by that absolute path because systemd&#39;s minimal <code>PATH</code> can&#39;t resolve a bare <code>tamias-driver-bupha</code>.</p><h2 id="install-and-deploy-the-bundle" tabindex="-1">Install and deploy the bundle <a class="header-anchor" href="#install-and-deploy-the-bundle" aria-label="Permalink to &quot;Install and deploy the bundle&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git:9aia/bupha//libraries/ci-gate#main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span></span></code></pre></div><p><code>deploy</code> does two things:</p><ol><li>Runs the kind driver&#39;s <code>deploy</code> verb, which merges the bundle&#39;s <code>fleet.toml</code> with the manifest&#39;s <code>provider.ingress</code> block and writes the operator config to <code>~/.config/bupha/bundles/ci-gate.toml</code> — one file per bundle, under <code>~/.config/bupha/bundles/</code>. The fleet itself (<code>[[repo]]</code> set, <code>[runner]</code>, <code>[status]</code>, <code>[worker]</code>) lives in the payload&#39;s <code>fleet.toml</code>; only the manifest-owned fields (<code>tunnel.public_url</code>, <code>trigger.listen</code>/<code>kind</code>) come from <code>tamias.yaml</code>.</li><li>Renders each <code>provider.services[]</code> entry as a per-user unit named <code>&lt;provider.name&gt;-&lt;service&gt;</code> — for ci-gate that&#39;s <code>bupha-watch.service</code> and <code>bupha-worker.service</code> (see <a href="/tamias/how-to/provision-a-service.html">Provision and service</a> for the unit rendering contract).</li></ol><h2 id="pick-an-ingress-mode-—-enable-one-service" tabindex="-1">Pick an ingress mode — enable ONE service <a class="header-anchor" href="#pick-an-ingress-mode-—-enable-one-service" aria-label="Permalink to &quot;Pick an ingress mode — enable ONE service&quot;">​</a></h2><p>ci-gate declares two services, one per ingress mode:</p><table tabindex="0"><thead><tr><th>unit</th><th>verb</th><th>mode</th></tr></thead><tbody><tr><td><code>bupha-watch.service</code></td><td><code>tamias-driver-bupha host --config ~/.config/bupha/bundles/ci-gate.toml</code></td><td>standalone: the bundle&#39;s own webhook listener (<code>provider.ingress</code>) → queue → pipeline. For hosts with no peregrin.</td></tr><tr><td><code>bupha-worker.service</code></td><td><code>tamias-driver-bupha worker --config ~/.config/bupha/bundles/ci-gate.toml</code></td><td>substrate: polls <code>kind=&quot;ci-job&quot;</code> entities on the peregrin node named by <code>[worker] node</code> in the generated config. For deployments where the ci-ingress campaign owns webhook ingress.</td></tr></tbody></table><p>Enable exactly one — both at once fight over the listener port and double-run pushes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># standalone mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bupha-watch</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># substrate mode (the org&#39;s production shape)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bupha-worker</span></span></code></pre></div><p>A substrate-mode bundle still declares <code>provider.ingress</code> — it is the standalone fallback and the source of <code>tunnel.public_url</code> / <code>trigger.listen</code> in the generated config — but only the worker unit runs.</p><h2 id="register-the-forge-hooks" tabindex="-1">Register the forge hooks <a class="header-anchor" href="#register-the-forge-hooks" aria-label="Permalink to &quot;Register the forge hooks&quot;">​</a></h2><p><code>provider.ingress[].hooks[]</code> is declarative: <code>tamias deploy</code> prints a hint but never registers live hooks. Registration is an explicit reviewable step:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # show the plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # upsert GitHub webhooks</span></span></code></pre></div><p>For the substrate mode the webhook URL fronts the peregrin campaign listener instead — the ci-ingress bundle&#39;s own <code>github-webhook</code> node owns <code>repos[]</code>, so no <code>hooks[]</code> are registered from tamias at all.</p><h2 id="operate-the-fleet" tabindex="-1">Operate the fleet <a class="header-anchor" href="#operate-the-fleet" aria-label="Permalink to &quot;Operate the fleet&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # provider: blocks + unit state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # JSON probe (listener + unit)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # per-unit is-active/is-enabled</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lines</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # journalctl over both units</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # foreground exec, no service manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci-gate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # units + bundles/ci-gate.toml + store entry</span></span></code></pre></div><p>The driver&#39;s full verb set is <code>install</code>/<code>deploy</code>/<code>uninstall</code>/<code>hooks</code>/ <code>health</code>/<code>status</code>/<code>logs</code>/<code>host</code>/<code>worker</code>/<code>config-schema</code> — <code>tamias driver exec</code> passes the verb through verbatim, and <code>tamias driver config-schema ci-gate</code> prints the JSON Schema of the operator config <code>deploy</code> writes. For the entity-plane worker&#39;s <code>[worker]</code> block (<code>node</code>, <code>node_token_env</code>, <code>labels</code>) and the <code>runsOn</code> routing it feeds, see bupha&#39;s <a href="https://github.com/9aia/bupha" target="_blank" rel="noreferrer">distributed runners</a> docs.</p><p>Secrets are env-var <strong>names</strong> only — <code>secret_env</code>/<code>token_env</code> in <code>fleet.toml</code> resolve env → cuora (<code>cuora://bupha/&lt;NAME&gt;</code>) → keyring. Seed values with <code>printf &#39;%s&#39; &quot;$VALUE&quot; | cuora put cuora://bupha/&lt;NAME&gt;</code>; never write a secret into either file.</p>`,25)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
